import { test, expect } from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';
import { createServer } from 'node:http';

// The edge serves the single NexusNXS AI document (generated by sync-ai-shell)
// with its own nonce CSP; the local service is offline here (readyz 503).
let server, origin;
test.beforeAll(async () => {
  const { default: worker } = await import('../../dist/server/index.js');
  const shell = await worker.fetch(new Request('https://ai.nexusnxs.com/', { headers: { accept: 'text/html' } }), {
    ASSETS: { fetch: async () => new Response('', { status: 404 }) },
  }, { waitUntil() {}, passThroughOnException() {} });
  const headers = { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store',
    'Content-Security-Policy': shell.headers.get('content-security-policy'), 'Permissions-Policy': shell.headers.get('permissions-policy') };
  const html = await shell.text();
  server = createServer((request, response) => {
    const url = new URL(request.url, 'http://localhost');
    if (url.pathname === '/') { response.writeHead(200, headers); response.end(html); }
    else if (url.pathname === '/readyz') { response.writeHead(503, { 'Content-Type': 'application/json' }); response.end('{"status":"offline","retryAfter":8}'); }
    else if (url.pathname.startsWith('/api/')) { response.writeHead(503, { 'Content-Type': 'application/json' }); response.end('{"error":"Servizio momentaneamente non disponibile"}'); }
    else { response.writeHead(404); response.end(); }
  });
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  origin = `http://127.0.0.1:${server.address().port}`;
});
test.afterAll(async () => {
  server.closeAllConnections();
  await new Promise(resolve => server.close(resolve));
});

async function open(page, viewport) {
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  page.on('console', message => { if (/Content Security Policy|Refused to/i.test(message.text())) errors.push(message.text()); });
  await page.setViewportSize(viewport);
  await page.goto(origin);
  await expect(page.locator('.app .stage .composer')).toBeVisible();
  await expect.poll(() => page.locator('canvas.core').getAttribute('data-backend')).toMatch(/^(webgpu|canvas)$/);
  return errors;
}

for (const viewport of [{ width: 320, height: 568 }, { width: 844, height: 390 }, { width: 1440, height: 900 }]) {
  test(`single AI app renders under the edge CSP at ${viewport.width}`, async ({ page }) => {
    await page.emulateMedia({ reducedMotion: viewport.width === 844 ? 'reduce' : 'no-preference' });
    const errors = await open(page, viewport);
    await expect(page.getByRole('heading', { name: /NexusNXS ragiona/ })).toBeVisible();
    await expect(page.getByRole('status').first()).toContainText(/Offline|In preparazione|Connessione/);
    expect(await page.evaluate(() => document.documentElement.scrollWidth > innerWidth)).toBe(false);
    // No classic shell and no visible scrollbars in the conversation area.
    await expect(page.locator('#coreCanvas, #prompt, .shell')).toHaveCount(0);
    expect(await page.locator('.scroll').evaluate(element => getComputedStyle(element).scrollbarWidth)).toBe('none');
    const audit = await new AxeBuilder({ page }).withTags(['wcag2a', 'wcag2aa', 'wcag21aa']).analyze();
    expect(audit.violations.map(item => `${item.id}: ${item.nodes.length}`)).toEqual([]);
    expect(errors).toEqual([]);
  });
}

test('sidebar hides on wide screens, persists, and the command palette opens with the keyboard', async ({ page }) => {
  await open(page, { width: 1440, height: 900 });
  await page.getByRole('button', { name: /Nascondi barra laterale/ }).click();
  await expect(page.locator('.app')).toHaveAttribute('data-collapsed', 'true');
  await page.reload();
  await expect(page.locator('.app')).toHaveAttribute('data-collapsed', 'true');
  await page.keyboard.press('Control+b');
  await expect(page.locator('.app')).toHaveAttribute('data-collapsed', 'false');
  await page.keyboard.press('Control+k');
  await expect(page.getByRole('dialog')).toBeVisible();
  await page.keyboard.press('Escape');
  await expect(page.getByRole('dialog')).toHaveCount(0);
});

test('an unavailable service ends the turn with a readable error instead of hanging', async ({ page }) => {
  await open(page, { width: 390, height: 844 });
  await page.getByRole('textbox', { name: 'Messaggio' }).fill('Ciao');
  await page.keyboard.press('Enter');
  await expect(page.locator('.thread .message.user')).toContainText('Ciao');
  await expect(page.locator('.thread .message.assistant')).toContainText(/non disponibile|non riuscita|Servizio/i);
  await expect(page.getByRole('button', { name: 'Invia', exact: true })).toBeVisible();
});
